import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"部署本地模型","description":"在电脑上部署语言模型或生图模型，用 MiniTavern 通过局域网连接。含 Ollama、LM Studio、A1111、ComfyUI 等。","frontmatter":{"title":"部署本地模型","description":"在电脑上部署语言模型或生图模型，用 MiniTavern 通过局域网连接。含 Ollama、LM Studio、A1111、ComfyUI 等。","head":[["meta",{"property":"og:title","content":"部署本地模型 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"在电脑上部署语言模型或生图模型，用 MiniTavern 通过局域网连接。含 Ollama、LM Studio、A1111、ComfyUI 等。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/local"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/local"}]]},"headers":[],"relativePath":"local/index.md","filePath":"local/index.md","lastUpdated":1786517442000}'),r={name:"local/index.md"};function i(l,t,n,s,c,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="部署本地模型" tabindex="-1">部署本地模型 <a class="header-anchor" href="#部署本地模型" aria-label="Permalink to &quot;部署本地模型&quot;">​</a></h1><p>MiniTavern 是 <strong>BYOK（自备密钥）</strong> 客户端：请求发往你配置的地址，不强制绑定某一家云厂商。<br> 「部署本地模型」指在<strong>自己的电脑</strong>上跑推理服务，再用手机上的 MiniTavern 通过局域网连接。</p><p>本栏目分两条线：</p><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>入口</th></tr></thead><tbody><tr><td><strong>语言模型部署</strong></td><td>聊天、续写、转写生图 prompt</td><td><a href="/ultra_guides/quickstart">30 分钟通关</a> · <a href="./tools">工具总览</a></td></tr><tr><td><strong>生图模型部署</strong></td><td><code>/imagine</code>、附件生图、背景图</td><td><a href="./image-gen/">生图概览</a></td></tr></tbody></table><p>没有 GPU、也不想装服务时，可先用 <a href="/ultra_guides/free-cloud/">免费云端</a> 拿试用 / 免费额度。</p><blockquote><p>MiniTavern <strong>本身不在手机上跑大模型或扩散模型</strong>。服务跑在电脑上，App 只负责角色卡、世界书、聊天与生图请求。</p></blockquote><h2 id="语言模型部署" tabindex="-1">语言模型部署 <a class="header-anchor" href="#语言模型部署" aria-label="Permalink to &quot;语言模型部署&quot;">​</a></h2><p>在电脑上运行大语言模型（Ollama、LM Studio、KoboldCPP 等），App 里填 <strong>自定义（OpenAI 兼容）</strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>建议</th></tr></thead><tbody><tr><td>电脑</td><td>Windows / macOS / Linux；内存建议 <strong>16GB+</strong></td></tr><tr><td>显卡（可选）</td><td>NVIDIA / Apple Silicon 更快；纯 CPU 也能跑</td></tr><tr><td>网络</td><td>手机与电脑同一 Wi‑Fi（勿用访客隔离网）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>工具</th><th>适合谁</th><th>默认端口</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ollama/install">Ollama</a></td><td>命令行省事、一键拉模型</td><td><code>11434</code></td></tr><tr><td><a href="/ultra_guides/lmstudio/install">LM Studio</a></td><td>图形界面、点选下载</td><td><code>1234</code></td></tr><tr><td><a href="/ultra_guides/koboldcpp/install">KoboldCPP</a></td><td>角色扮演社区常用</td><td><code>5001</code></td></tr><tr><td><a href="/ultra_guides/llamacpp/install">llama.cpp</a></td><td>直接跑 GGUF</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/localai/install">LocalAI</a></td><td>Docker / 一站式兼容层</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/jan/install">Jan</a> · <a href="/ultra_guides/textgen/install">text-generation-webui</a></td><td>其它图形或插件生态</td><td>见各页</td></tr></tbody></table><p>推荐顺序：<a href="/ultra_guides/quickstart">30 分钟通关</a> → <a href="./tools">工具总览</a> → <a href="./models">推荐模型</a> → <a href="/ultra_guides/connect-app/minitavern">在 MiniTavern 中配置</a> → 卡住查 <a href="/ultra_guides/troubleshoot">排错</a>。</p><h2 id="生图模型部署" tabindex="-1">生图模型部署 <a class="header-anchor" href="#生图模型部署" aria-label="Permalink to &quot;生图模型部署&quot;">​</a></h2><p>在电脑上跑 Stable Diffusion 系服务，App <strong>设置 → 生图 → 生图连接</strong> 选 A1111 或 ComfyUI。</p><table tabindex="0"><thead><tr><th>后端</th><th>默认端口</th><th>教程</th></tr></thead><tbody><tr><td><a href="./image-gen/a1111">A1111 / SD WebUI</a></td><td><code>7860</code></td><td>需 <code>--api --listen</code></td></tr><tr><td><a href="./image-gen/comfyui">ComfyUI</a></td><td><code>8188</code>（Desktop 常见 <code>8000</code>）</td><td>需 <code>--listen</code></td></tr></tbody></table><p>总览与硬件说明见 <a href="./image-gen/">生图模型部署</a>；填连接见 <a href="./image-gen/connect-app">连 App</a>。</p><h2 id="重要提醒" tabindex="-1">重要提醒 <a class="header-anchor" href="#重要提醒" aria-label="Permalink to &quot;重要提醒&quot;">​</a></h2><ul><li>手机里填的地址必须是电脑的 <strong>局域网 IP</strong>，<strong>不要</strong>填 <code>localhost</code> / <code>127.0.0.1</code>。</li><li>语言模型 Base URL 通常以 <code>/v1</code> 结尾（如 <code>http://192.168.1.8:11434/v1</code>）。</li><li>生图 A1111 必须开 <code>--api</code>；ComfyUI 必须能局域网访问。</li><li>防火墙放行对应端口；勿把未鉴权 API 暴露到公网。</li></ul>',17)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
